local M={pending={}}
function M.declared(path)
 if type(path)~='string' or not path:match('^[%w_./-]+$') or path:find('..',1,true) then return false end
 local parent,name=path:match('^(.*)/([^/]+)$')
 return parent and dirs[parent] and dirs[parent]:find('\n'..name..'\n',1,true)~=nil or false
end
function M.allowPending(path)
 if not M.declared(path) then return false end
 M.pending[path]=true
 return true
end
