function M.metadata(path)
 if not M.declared(path) then return nil end
 local parent,name=path:match('^(.*)/([^/]+)$');local values=metadata[parent]
 if not values then return nil end
 local _,at=values:find('\n'..name..'|',1,true);if not at then return nil end
 local stop=values:find('\n',at+1,true)
 local w,h,hash=values:sub(at+1,stop-1):match('^(%d+)|(%d+)|([a-f0-9]+)$')
 return w and {width=tonumber(w),height=tonumber(h),sha256=hash}or nil
end
function M.imageHash(raw)
 return love.data.encode('string','hex',love.data.hash('sha256',raw))
end
return M
